document.addEventListener("DOMContentLoaded", function () {

    const form = document.getElementById("orderForm");

    if (!form) {
        console.log("Form not found!");
        return;
    }

    const name = document.getElementById("billing_first_name");
    const phone = document.getElementById("billing_phone");
    const address = document.getElementById("billing_address_1");


    // ==============================
    // Create error message elements
    // ==============================

    function createErrorElement(input) {

        let error = document.getElementById(input.id + "_error");

        if (!error) {

            error = document.createElement("div");

            error.id = input.id + "_error";

            error.className = "field-error";

            input.parentNode.appendChild(error);
        }

        return error;
    }


    // ==============================
    // Show error
    // ==============================

    function showError(input, message) {

        const error = createErrorElement(input);

        error.textContent = message;

        input.classList.add("input-error");
    }


    // ==============================
    // Remove error
    // ==============================

    function clearError(input) {

        const error = document.getElementById(
            input.id + "_error"
        );

        if (error) {
            error.textContent = "";
        }

        input.classList.remove("input-error");
    }


    // ==============================
    // Validate name
    // ==============================

    function validateName() {

        const value = name.value.trim();

        if (value === "") {

            showError(
                name,
                "Please enter your name."
            );

            return false;
        }

        if (value.length < 3) {

            showError(
                name,
                "Name must be at least 3 characters."
            );

            return false;
        }

        clearError(name);

        return true;
    }


    // ==============================
    // Validate phone
    // ==============================

    function validatePhone() {

        const value = phone.value.trim();

        if (value === "") {

            showError(
                phone,
                "Please enter your phone number."
            );

            return false;
        }


        // Bangladesh mobile number
        const phonePattern =
            /^01[3-9][0-9]{8}$/;


        if (!phonePattern.test(value)) {

            showError(
                phone,
                "Please enter a valid Bangladesh phone number. Example: 01740154669"
            );

            return false;
        }


        clearError(phone);

        return true;
    }


    // ==============================
    // Validate address
    // ==============================

    function validateAddress() {

        const value = address.value.trim();

        if (value === "") {

            showError(
                address,
                "Please enter your complete address."
            );

            return false;
        }


        if (value.length < 10) {

            showError(
                address,
                "Please enter your complete address."
            );

            return false;
        }


        clearError(address);

        return true;
    }


    // ==============================
    // Form Submit
    // ==============================

    form.addEventListener("submit", function (e) {

        const nameValid = validateName();

        const phoneValid = validatePhone();

        const addressValid = validateAddress();


        if (
            !nameValid ||
            !phoneValid ||
            !addressValid
        ) {

            e.preventDefault();

            // Focus first invalid field
            if (!nameValid) {

                name.focus();

            } else if (!phoneValid) {

                phone.focus();

            } else if (!addressValid) {

                address.focus();

            }

            return false;
        }

    });


    // ==============================
    // Real-time validation
    // ==============================

    name.addEventListener("input", function () {

        validateName();

    });


    phone.addEventListener("input", function () {

        validatePhone();

    });


    address.addEventListener("input", function () {

        validateAddress();

    });

});
</script>
